}

.nav-home { display: none; }

.nav-section { margin-bottom: 2px; }
.nav-section-label {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--text-dim);
  padding: 16px 16px 5px;
}
.nav-item {
  display: flex;
  align-items: center;
  width: 100%;
  text-align: left;
  background: none;
  border: none;
  padding: 5px 16px;
  font-size: 13px;
  font-weight: 400;
  color: var(--text-tertiary);
  cursor: pointer;
  transition: color 0.1s, background 0.1s;
  font-family: var(--font-sans);
  border-radius: 0;
  letter-spacing: -0.01em;
  gap: 8px;
}
.nav-item:hover { color: var(--text-primary); background: rgba(255,255,255,0.04); }
.nav-item.active { color: var(--text-primary); background: rgba(255,255,255,0.06); }

/* ══ Content ══════════════════════════════════════════════════ */
.content {
  flex: 1;
  overflow-y: auto;
  padding: 64px clamp(28px, 7vw, 96px) 110px;
  scrollbar-width: thin;
  scrollbar-color: var(--surface-4) transparent;
}

/* ══ Page typography ══════════════════════════════════════════ */
.page {
  max-width: 980px;
  animation: page-in 420ms cubic-bezier(.2,.7,.2,1) both;
}
@keyframes page-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) { .page { animation: none; } }
.page-header { margin-bottom: 40px; }
.page-eyebrow {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--blue-l);
  margin-bottom: 10px;
  font-family: var(--font-mono);
}
.page-title-row { display: flex; align-items: baseline; gap: 14px; flex-wrap: wrap; margin-bottom: 8px; }
.page h1 {
  font-size: clamp(2.2rem, 4vw, 3.2rem);
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.15;
  letter-spacing: -0.03em;
}
.page h2 {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-dim);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  margin: 40px 0 16px;
}
.page p { color: var(--text-secondary); margin-bottom: 12px; line-height: 1.7; }
.page ul { padding-left: 18px; margin-bottom: 16px; }
.page li { margin-bottom: 6px; color: var(--text-secondary); }
.lead { font-size: 1.05rem; color: var(--text-secondary); line-height: 1.6; font-weight: 400; }

/* ══ Terminal window ══════════════════════════════════════════ */
.terminal {
  position: relative;
  border-radius: var(--r-lg);

